package class43;public class xToThePowerN {    public static double Xpower(double x,int n){            if (n == 0) return 1;            if (n == 1) return x;            double r = Xpower(x, n / 2);            return (n % 2 == 0) ? (r * r) : (r * r * x);    }    public  static double neg(double x,int n){        if(n<0){            n=n*-1;        }else{           return Xpower(x,n);        }        double ans= Xpower(x,n);        return 1/ans;    }    public static void main(String[] args) {        System.out.println(neg(-2.00000,5));    }}